import os
import re
import csv
from datetime import date, timedelta

LOG_DIR = "/app/logs"
TODAY = date(2025, 8, 12)
LAST_7_START = TODAY - timedelta(days=6)
LAST_30_START = TODAY - timedelta(days=29)
MONTH_START = TODAY.replace(day=1)

FNAME_RE = re.compile(r"^(\d{4}-\d{2}-\d{2})_.*\.log$")
LINE_RE = re.compile(r"\[(ERROR|WARNING|INFO)\]")

severities = ["ERROR", "WARNING", "INFO"]
periods = ["today", "last_7_days", "last_30_days", "month_to_date", "total"]
counts = {p: {s: 0 for s in severities} for p in periods}

for fname in os.listdir(LOG_DIR):
    m = FNAME_RE.match(fname)
    if not m:
        continue
    file_date = date.fromisoformat(m.group(1))

    sev_counts = {s: 0 for s in severities}
    with open(os.path.join(LOG_DIR, fname), "r", errors="replace") as f:
        for line in f:
            lm = LINE_RE.search(line)
            if lm:
                sev_counts[lm.group(1)] += 1

    for s in severities:
        counts["total"][s] += sev_counts[s]
        if file_date == TODAY:
            counts["today"][s] += sev_counts[s]
        if LAST_7_START <= file_date <= TODAY:
            counts["last_7_days"][s] += sev_counts[s]
        if LAST_30_START <= file_date <= TODAY:
            counts["last_30_days"][s] += sev_counts[s]
        if MONTH_START <= file_date <= TODAY:
            counts["month_to_date"][s] += sev_counts[s]

with open("/app/summary.csv", "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["period", "severity", "count"])
    for p in periods:
        for s in severities:
            writer.writerow([p, s, counts[p][s]])

print("done")

